# genex.toml
[render.look]
tonemapper = "agx-punchy"
exposure = "auto"
ev_compensation = 0.5

// src/main.rs
use genex::render::{Fog, Grading, RenderConfig};
game.render_settings(
    RenderConfig::from_build() // keeps genex.toml's [render]
        .fog(Fog::default().with_density(0.02).with_height(0.3, 0.0))
        .exposure_curve(&[(-8.0, -6.0), (0.0, 0.0)]) // the night stays darker than the day
        .grading(Grading::NEUTRAL.with_vibrance(1.1)), // last, for taste
);

// src/game.rs
use genex::render::{Environment, Moon, SkyParams};

fn draw(world: &World, frame: &mut Frame) {
    let sun = world.sun_direction; // towards the sun; below the horizon at night
    let moon = Moon::new([-sun.x, -sun.y, -sun.z]); // opposite the sun: a full moon
    frame.sun(sun, Color::WHITE, 3.0); // white: the sky colours it
    frame.environment(Environment::Sky(SkyParams::default().with_moon(Some(moon))));
}
